}

#[derive(Clone, Default)]
struct RowSplitState {
    separator: String,
    max_split: Option<usize>,
    regex_mode: bool,
    pieces: Vec<String>,
    separator_span: Option<Span>,
}

#[derive(Clone, Default)]
struct WordSplitState {
    min_length: Option<usize>,
    graphemes: bool,
    pieces: Vec<String>,
